// 1) HMAC signature check  2) replay window (5 min)  3) de-duplicate by delivery id (redeliveries/retries)
const crypto = require('crypto');
const secret = $env.FC_WEBHOOK_SECRET;
if (!secret) throw new Error('FC_WEBHOOK_SECRET is not set in the n8n environment');
const seen = $getWorkflowStaticData('global');
seen.ids = seen.ids || [];
const out = [];
for (const item of $input.all()) {
  const h = item.json.headers || {};
  const ts = h['x-fc-timestamp'];
  const sig = h['x-fc-signature'] || '';
  const body = JSON.stringify(item.json.body);
  const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(`${ts}.${body}`).digest('hex');
  const ok = sig.length === expected.length && crypto.timingSafeEqual(Buffer.from(sig), Buffer.from(expected));
  if (!ok) throw new Error('Invalid signature — event rejected');
  if (Math.abs(Date.now() / 1000 - Number(ts)) > 300) throw new Error('Stale event (replay protection)');
  const id = h['x-fc-delivery'];
  if (id && seen.ids.includes(id)) continue; // already handled
  if (id) { seen.ids.push(id); if (seen.ids.length > 500) seen.ids = seen.ids.slice(-500); }
  out.push({ json: { ...item.json.body, deliveryId: id } });
}
return out;

// Arabic Telegram message for every Future Creative event (photo + approve/reject buttons for new designs).
const e = $input.first().json;
const d = e.data || {};
const base = e.dashboard || '';
const link = (p) => (p ? base + p : base);
const abs = (u) => (u && !u.startsWith('http') ? base + u : u);
let text = `🔔 ${e.title}
`;
let photo = null, buttons = null;
switch (e.event) {
  case 'ad.ready_for_review':
    text += `الحساب: ${d.account?.name ?? ''}
الصيغة: ${d.format}${d.slideUrls?.length ? ` (${d.slideUrls.length + 1} شرائح)` : ''}
العنوان: ${d.headline ?? ''}
${d.dryRun ? '⚠️ معاينة تجريبية — غير قابلة للنشر
' : ''}${d.qcPassed ? '✅ اجتاز فحص الجودة' : '❌ لم يجتز فحص الجودة'}${d.requiresHuman ? ' · يحتاج نظرتك' : ''}

${(d.caption || '').slice(0, 600)}

مراجعة: ${link(d.reviewUrl)}`;
    photo = abs(d.imageUrl);
    if (d.qcPassed && !d.dryRun) buttons = { inline_keyboard: [[{ text: '✅ اعتماد', callback_data: `a:${d.adId}` }, { text: '❌ رفض', callback_data: `r:${d.adId}` }]] };
    break;
  case 'ad.approved': text += `بواسطة: ${d.by}`; break;
  case 'ad.rejected': text += `بواسطة: ${d.by}${d.note ? `
السبب: ${d.note}` : ''}`; break;
  case 'publication.published': text += `الحساب: ${d.account}
${d.publicUrl ? 'الرابط: ' + d.publicUrl : ''}`; break;
  case 'publication.scheduled': text += `الحساب: ${d.account}
موعد النشر: ${d.publishAt}`; break;
  case 'publication.failed': text += `الحساب: ${d.account ?? d.accountId}
السبب: ${d.reason}
${link('/posts?state=FAILED')}`; break;
  case 'publication.unknown': text += `الحساب: ${d.account}
${d.error}
تحقق في Metricool ثم قرر من: ${link('/posts?state=UNKNOWN')}`; break;
  case 'connection.lost': text += `الحساب: ${d.account}
${d.reason}
أعد الربط ثم «فحص كل الحسابات الآن».`; break;
  case 'approvals.reminder': text += `${d.totalPending} تصميم ينتظر منذ أكثر من ${d.hours} ساعات:
` + (d.items || []).map((i) => `• ${i.account}: ${i.headline ?? ''} — ${link(i.reviewUrl)}`).join('
'); break;
  case 'daily.digest':
    text += `📅 ${d.date}
تصاميم جديدة: ${d.created} · بانتظار موافقتك: ${d.pendingApprovals}
مؤكدة النشر اليوم: ${d.publishedVerified} · مجدولة: ${d.scheduledToday}
فاشلة: ${d.failed} · غير مؤكدة: ${d.unknown}
إنفاق الذكاء الاصطناعي اليوم: $${d.aiSpendUsd}
` + ((d.upcoming || []).length ? `
القادم:
` + d.upcoming.map((u) => `• ${u.at} — ${u.account}: ${u.headline ?? ''}`).join('
') : '') + `

${link(d.approvalsUrl)}`;
    break;
  case 'system.alert': text = `${d.level === 'CRITICAL' ? '🚨' : d.level === 'ERROR' ? '🔴' : d.level === 'WARNING' ? '🟡' : 'ℹ️'} ${d.title}
${d.message}
(${d.code})`; break;
  case 'report.weekly': {
    const m = d.metrics || {};
    text += `منشورات مؤكدة: ${m.posts ?? 0} · بمقاييس: ${m.withMetrics ?? 0}
الوصول: ${m.reach ?? 0} · المشاهدات: ${m.views ?? 0}
الحفظ+المشاركة: ${(m.saves ?? 0) + (m.shares ?? 0)} · متوسط التفاعل: ${m.avgEngagement ?? '—'}%
${m.reelSkipRatePct != null ? `تخطي الريلز: ${m.reelSkipRatePct}%
` : ''}
التوصيات:
• ${(d.recommendations || []).slice(0, 5).join('
• ')}

${link('/reports')}`;
    break;
  }
  case 'test.ping': text = `✅ الربط بين مطبعة إبداع المستقبل و n8n يعمل.
${d.message ?? ''}`; break;
  default: text += JSON.stringify(d).slice(0, 800);
}
return [{ json: { text: text.slice(0, photo ? 1000 : 4000), photo, buttons } }];

const tg = async (method, body) => this.helpers.httpRequest({ method: 'POST', url: `${$env.TELEGRAM_API_BASE || 'https://api.telegram.org'}/bot${$env.TELEGRAM_BOT_TOKEN}/${method}`, body, json: true });
// Sends to Telegram (token and chat from the n8n environment). Falls back to text if the photo cannot be fetched.
const { text, photo, buttons } = $input.first().json;
if (!$env.TELEGRAM_BOT_TOKEN || !$env.TELEGRAM_CHAT_ID) throw new Error('Set TELEGRAM_BOT_TOKEN and TELEGRAM_CHAT_ID in .env');
const chat_id = $env.TELEGRAM_CHAT_ID;
let res;
if (photo) {
  try { res = await tg('sendPhoto', { chat_id, photo, caption: text, reply_markup: buttons || undefined }); }
  catch (err) { res = await tg('sendMessage', { chat_id, text: `${text}\n\n(تعذر إرفاق الصورة)`, reply_markup: buttons || undefined, disable_web_page_preview: true }); }
} else res = await tg('sendMessage', { chat_id, text, reply_markup: buttons || undefined, disable_web_page_preview: true });
return [{ json: { ok: !!res.ok } }];

